 * @hidden N
 */
scwin.searchKeywrd = function () {
    $.ajax({ type: "POST", url: "/ods/integsrch.do", data: $("#keywrdForm").serialize(), async: false, success: function(data) {
                (($c.util.getComponent('keywrdList')) && ($c.util.getComponent('keywrdList')).removeAll ? ($c.util.getComponent('keywrdList')).removeAll() : (($c.util.getComponent('keywrdList')) && ($c.util.getComponent('keywrdList')).setValue ? ($c.util.getComponent('keywrdList')).setValue('') : void 0)).append(data);
                makeTableOdd();
