/**
 * @method
 * @name modiKeywrd
 * @description modi Keywrd 처리
 * @param {String} tdId tdId
 * @param {String} ipt_keywrdNm ipt_keywrdNm
 * @param {*} ipt_keywrdNo ipt_keywrdNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modiKeywrd = async function (tdId, ipt_keywrdNm, ipt_keywrdNo) {
    const btnVal = $('#modBtn' + tdId).val();
    if ("변경" === btnVal) {
        $('#keywrdTd' + tdId).empty().append("<input type='text' id='chgKeywrdNm" + tdId + "' name='chgKeywrdNm" + tdId + "' value='" + ipt_keywrdNm + "' style='width:90%;'>");
        $('#modBtn' + tdId).val("저장");
    } else {
        if ($('#chgKeywrdNm' + tdId).val().length === 0) {
            await $c.win.alert("변경할 키워드를 입력해주시기 바랍니다.");
            return;
        }
        if (!await $c.win.confirm("키워드를 변경하시겠습니까?")) {
            $('#keywrdTd' + tdId).empty().append(ipt_keywrdNm);
            $('#modBtn' + tdId).val("변경");
            return;
        }
        $c.util.getComponent('ipt_method').setValue("updateKeywrdNm");
        await scwin.chkDupKeywrd($('#chgKeywrdNm' + tdId).val());
        if (scwin.dupCnt === 0) {
            $c.util.getComponent('ipt_modKeywrdNm').setValue($('#chgKeywrdNm' + tdId).val());
            $c.util.getComponent('ipt_keywrdNo').setValue(ipt_keywrdNo);
            await scwin.tx_fn_modiKeywrd();
        } else {
            await $c.win.alert("이미 사용중인 키워드입니다.");
            return;
        }
    }
};

/**
 * @method
 * @name delKeywrd
 * @description del Keywrd 처리
 * @param {*} ipt_keywrdNo ipt_keywrdNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delKeywrd = async function (ipt_keywrdNo) {
    if (!await $c.win.confirm("키워드를 삭제하시겠습니까?")) {
        return;
    }
    $c.util.getComponent('ipt_method').setValue("deleteKeywrd");
    $c.util.getComponent('ipt_keywrdNo').setValue(ipt_keywrdNo);
    await scwin.tx_fn_delKeywrd();
};

/**
 * @method
 * @name regKeywrd
 * @description reg Keywrd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.regKeywrd = async function () {
    if ($c.util.getComponent('ipt_newKeywrdNm').getValue().length === 0) {
        await $c.win.alert("신규 등록 키워드를 입력해주시기 바랍니다.");
        return;
    }
    if (await $c.win.confirm("키워드를 등록하시겠습니까?")) {
        await scwin.chkDupKeywrd($c.util.getComponent('ipt_newKeywrdNm').getValue());
        if (status === "false") {
            return;
        }
        if (scwin.dupCnt === 0) {
            $c.util.getComponent('ipt_regKeywrdNm').setValue(($c.util.getComponent("ipt_newKeywrdNm").getValue() || ''));
            $c.util.getComponent('ipt_method').setValue("insertKeywrdNm");
            await scwin.tx_fn_regKeywrd();
        } else {
            await $c.win.alert("이미 사용중인 키워드입니다.");
            return;
        }
    }
};

/**
 * @method
 * @name setIntegSrchNo
 * @description set Integ Srch No 처리
 * @param {*} integSrchNo integSrchNo
 * @param {*} chkObj chkObj
 * @returns {void}
 * @hidden N
 */
scwin.setIntegSrchNo = function (integSrchNo, chkObj) {
    if (chkObj.checked === true) {
        if (scwin.integSrchNoText.length > 0) {
            scwin.integSrchNoArray = scwin.integSrchNoText.split(",");
            for (let i = 0, j = scwin.integSrchNoArray.length; i < j; i++) {
                let arrayIntegSrchNo = scwin.integSrchNoArray[i];
                if (arrayIntegSrchNo === integSrchNo) {
                    return;
                }
            }
            scwin.integSrchNoText += "," + integSrchNo;
        } else {
            scwin.integSrchNoText = integSrchNo;
        }
    } else {
        if (scwin.integSrchNoText.length > 0) {

            scwin.integSrchNoArray = scwin.integSrchNoText.split(",");
            for (let i = 0, j = scwin.integSrchNoArray.length; i < j; i++) {
                arrayIntegSrchNo = scwin.integSrchNoArray[i];
                if (arrayIntegSrchNo === integSrchNo) {
                    scwin.integSrchNoText = scwin.integSrchNoText.substring(0, scwin.integSrchNoText.indexOf(integSrchNo) - 1) + scwin.integSrchNoText.substring(scwin.integSrchNoText.indexOf(integSrchNo) + integSrchNo.length + 1);
                }
            }
        }
    }
};

/**
 * @method
 * @name clickKeyword
 * @description click Keyword 처리
 * @param {*} ele ele
 * @returns {void}
 * @hidden N
 */
scwin.clickKeyword = function (ele) {
    $('.sort a').on('click', function() {
            if ($(this).hasClass('active')) {
                return false;
            }
            $('.sort a').removeClass('active');
            $(this).addClass('active');
    });
};

